const chatId = String($json.message?.chat?.id || '');
const text = ($json.message?.text || '').trim();
const m = text.match(/^\/weekly\s+(\S+)\s+([\s\S]+)/i);

if (!chatId) throw new Error('No chat id in Telegram payload');

if (!m) {
  return {
    json: {
      chatId,
      sendTo: '',
      subject: '',
      message: '',
      ackText: 'Usage: /weekly <toEmail> <weekLabel>'
    }
  };
}

const toEmail = m[1];
const weekLabel = m[2].trim();
return {
  json: {
    chatId,
    sendTo: toEmail,
    subject: `Weekly operations report - ${weekLabel}`,
    message: [
      `Weekly report (${weekLabel})`,
      '',
      '1) Pipeline: TODO',
      '2) Sales activities: TODO',
      '3) Delivery status: TODO',
      '4) Risks/blockers: TODO',
      '',
      'Prepared automatically via n8n draft workflow.'
    ].join('\n'),
    ackText: `Weekly report prepared for ${toEmail}`
  }
};
